from pwn import *

def create_instruction_sequence():
    sequence = []

    # Main bruteforce loop
    sequence.extend([
        0x70, 0x00,           # ENT - try to enter enclave
        0xA3, 0x08,           # JEQ r3,0,8 (jump if success)
        0xC0, 0x00,           # INC r0
        0xB0, 0x00,           # JMP to start
    ])

    # Success: read flag and store
    for i in range(32):
        sequence.extend([
            0xD1, i,          # MOVFS r1,i (read from safe_rom)
            0x61, 0x80 + i    # MOVT r1,128+i (store sequentially)
        ])

    # Pad to 256 bytes
    while len(sequence) < 256:
        sequence.extend([0x00, 0x00])

    return bytes(sequence)

def main():
    # Connect to server
    conn = remote('rev.chal.csaw.io', 8000)

    # Create and send payload
    payload = create_instruction_sequence()
    hex_string = payload.hex()
    conn.sendline(hex_string.encode())

    # Get response
    try:
        response = conn.recvall().decode('latin-1')
        print("Server response:")
        print(response)

        # Try to extract memory dump
        lines = response.split('\n')
        for line in lines:
            if len(line) > 64 and not line.startswith('WARNING') and not line.startswith('ERROR'):
                try:
                    # Remove 'xx' and spaces, get actual hex values
                    hex_vals = [x for x in line.split() if x != 'xx']
                    if hex_vals:
                        print("\nExtracted memory values:", ' '.join(hex_vals))
                except:
                    continue

    except Exception as e:
        print(f"Error processing response: {e}")
    finally:
        conn.close()

if __name__ == '__main__':
    main()

