#!/usr/bin/env python3
from pwn import *
import time

def send_instructions(hex_data, timeout=5):
    try:
        conn = remote('rev.chal.csaw.io', 8000, timeout=timeout)
        conn.recvuntil(b'WELCOME\n', timeout=timeout)
        conn.sendline(hex_data.encode())
        result = conn.recvall(timeout=timeout).decode()
        conn.close()
        return result
    except Exception as e:
        return None

def build_entry_sequence(key):
    # Key in R0
    sequence = [f"{key:04x}"]

    # ENT instruction
    sequence.append("7000")

    # Store entry result in RAM
    sequence.append("32FE")  # Move R3 (status) to RAM[0xFE]

    # If entry successful, read flag
    # Read first 64 bytes of safe_rom into RAM
    for i in range(64):
        sequence.append(f"D0{i:02x}")  # MOVFS from safe_rom[i] to R0
        sequence.append(f"30{i:02x}")  # MOVT from R0 to RAM[i]

    # Read potential flag area (0xF0-0xFF)
    for addr in range(0xF0, 0x100):
        sequence.append(f"D1{addr:02x}")  # MOVFS from safe_rom[addr] to R1
        sequence.append(f"31{addr:02x}")  # MOVT from R1 to RAM[addr]

    # Exit
    sequence.append("8000")

    return "".join(sequence)

def parse_for_flag(output):
    if not output:
        return None

    # Look for successful ENT
    if "SAFE ENTRY SUCCESS" in output or "emode=1" in output:
        log.info("Found successful entry!")

    # Look for flag pattern in ascii representation
    if 'flag{' in output:
        try:
            start = output.index('flag{')
            end = output.index('}', start) + 1
            return output[start:end]
        except:
            pass

    # Try to parse RAM dumps
    try:
        ram_values = []
        for line in output.split('\n'):
            if 'RAM[' in line and ']: ' in line:
                # Extract hex values after the colon
                values = line.split(']: ')[1].strip().split()
                ram_values.extend(values)

        # Convert to bytes and look for flag
        if ram_values:
            hex_data = ''.join(ram_values)
            data = bytes.fromhex(hex_data)
            text = data.decode('ascii', errors='ignore')

            if 'flag{' in text:
                start = text.index('flag{')
                end = text.index('}', start) + 1
                return text[start:end]
    except:
        pass

    return None

def try_key_range(base, count=16):
    for offset in range(count):
        key = base + offset
        log.info(f"Testing key: {key:04x}")

        hex_data = build_entry_sequence(key)
        output = send_instructions(hex_data)

        if output and "SAFE" in output:
            log.info(f"Interesting response for key {key:04x}")

            # Try nearby values
            for delta in [-2, -1, 1, 2]:
                test_key = key + delta
                if not (0 <= test_key <= 0x3FFF):
                    continue

                log.info(f"Testing nearby key: {test_key:04x}")
                test_data = build_entry_sequence(test_key)
                test_output = send_instructions(test_data)

                flag = parse_for_flag(test_output)
                if flag:
                    return flag

        elif output and "emode" in output:
            log.info(f"Potential valid key found: {key:04x}")
            flag = parse_for_flag(output)
            if flag:
                return flag

        time.sleep(0.1)

    return None

def main():
    context.log_level = 'info'

    # Try promising ranges based on previous attempts
    promising_ranges = [
        (0x1990, 32),  # Around 0x1998
        (0x3990, 32),  # Around 0x3998
        (0x27F0, 32),  # Around 0x27FC
    ]

    for base, count in promising_ranges:
        flag = try_key_range(base, count)
        if flag:
            log.success(f"Found flag: {flag}")
            return flag

    # Try additional ranges
    additional_ranges = [
        (0x1000, 16),
        (0x2000, 16),
        (0x3000, 16),
    ]

    for base, count in additional_ranges:
        flag = try_key_range(base, count)
        if flag:
            log.success(f"Found flag: {flag}")
            return flag

    log.failure("No flag found")
    return None

if __name__ == "__main__":
    main()

